<!doctype html><html><head><meta charset=utf-8><title>Conscious</title><style>body{font-family:sans-serif;max-width:640px;margin:40px auto;padding:0 16px}textarea{width:100%;height:140px}button{padding:8px 16px}.c{background:#f3f3f8;padding:10px;margin:8px 0;border-radius:8px}</style></head><body><h1>Conscious</h1><p>A private journal that notices your patterns. Everything runs in your browser.</p><textarea id=t placeholder="How was your day?"></textarea><br><button onclick="r()">Reflect</button><div id=o></div><h3>History</h3><div id=h></div>
<script>
const P={pos:['happy','great','proud','excited','good','calm','grateful','fun','love'],neg:['tired','stress','stressed','anxious','sad','angry','worried','bad','overwhelmed','behind']};
function r(){const v=t.value;if(!v.trim())return;const w=v.toLowerCase().split(/\W+/);let p=0,n=0,m={};w.forEach(x=>{if(P.pos.includes(x))p++;if(P.neg.includes(x))n++;if(x.length>4)m[x]=(m[x]||0)+1});
const top=Object.entries(m).sort((a,b)=>b[1]-a[1]).slice(0,3).map(e=>e[0]);const mood=p>n?'positive':n>p?'strained':'neutral';
const q=mood=='strained'?'What is one thing you can drop this week?':mood=='positive'?'What made today work, and how can you repeat it?':'What did you want more of today?';
o.innerHTML='<div class=c>Mood: <b>'+mood+'</b><br>Themes: '+top.join(', ')+'<br>Prompt: '+q+'</div>';
const H=JSON.parse(localStorage.c||'[]');H.unshift({d:new Date().toLocaleDateString(),mood,top});localStorage.c=JSON.stringify(H.slice(0,20));s()}
function s(){const H=JSON.parse(localStorage.c||'[]');h.innerHTML=H.map(e=>'<div class=c>'+e.d+' - '+e.mood+' - '+e.top.join(', ')+'</div>').join('')}s()
</script></body></html>
E
